function nearestFractionLabel(inches){
  let best = FRACTIONS[0];
  for(const f of FRACTIONS) if(Math.abs(f-inches) < Math.abs(best-inches)) best = f;
  const n = Math.round(best*64);
  const gcd=(a,b)=>b?gcd(b,a%b):a, g=gcd(n,64);
  const num=n/g, den=64/g;
  return den===1 ? `${num}"` : `${num}/${den}"`;
}

function thinLensImageDistance(f,u){ // f,u in inches; u optional (subject distance)
  if(!u || !isFinite(u)) return f; // infinity focus
  const uIn = u*12; // feet → inches
  const v = 1 / (1/f - 1/uIn);
  return v;
}

function imageCircleGuess(f){ return 1.5 * f; } // conservative

function suggestDrillSizes(focalIn, targetN){
  const needed = focalIn/targetN;
  const picks = FRACTIONS.map(x=>({x,err:Math.abs(x-needed)})).sort((a,b)=>a.err-b.err).slice(0,3);
  return {needed, picks: picks.map(p=>({label:nearestFractionLabel(p.x), value:p.x, N:Math.round(focalIn/p.x)}))};
}

function roundHuman(t){
  const steps = [1/8, 1/4, 1/2, 1, 2, 4, 8, 16, 32];
  return steps.reduce((best,s)=>Math.abs(s-t)<Math.abs(best-t)?s:best, steps[0]);
